<template><div class="admin-page"><header class="page-header"><h1>素材库</h1><div><el-button type="primary" @click="create">新增素材库</el-button><el-button @click="router.push('/admin/relay-stations')">管理中转站</el-button></div></header><div class="library-grid"><article v-for="item in libraries" :key="item.stationId" class="library-card"><h2>{{item.name}}</h2><p>{{item.provider}} · {{item.stationName}}</p><el-button link type="primary" @click="edit(item.stationId)">编辑素材库配置</el-button><el-button link @click="copy(item.stationId)">复制素材库</el-button></article></div><el-dialog v-model="dialog" title="素材库模板" width="620px"><el-form v-if="draft" label-position="top"><el-form-item label="素材库名称"><el-input v-model="draft.name"/></el-form-item><el-form-item label="上传 URL"><el-input v-model="draft.uploadUrl"/></el-form-item><el-form-item label="查询 URL"><el-input v-model="draft.queryUrl"/></el-form-item><el-form-item label="鉴权头"><el-input v-model="draft.authHeader"/></el-form-item><el-form-item label="鉴权前缀"><el-input v-model="draft.authPrefix"/></el-form-item><div class="field-grid"><el-form-item label="URL 字段"><el-input v-model="draft.fields.url"/></el-form-item><el-form-item label="类型字段"><el-input v-model="draft.fields.assetType"/></el-form-item><el-form-item label="名称字段"><el-input v-model="draft.fields.name"/></el-form-item><el-form-item label="ProjectName 字段"><el-input v-model="draft.fields.projectName"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage}from'element-plus';import{useRouter}from'vue-router';import{adminApi,type RelayStation}from'@/api/admin';const router=useRouter(),stations=ref<RelayStation[]>([]),dialog=ref(false),draft=ref<any>(null),source=ref<RelayStation|null>(null);const libraries=ref<any[]>([]);const load=async()=>{stations.value=(await adminApi.getRelayStations()).data.stations;libraries.value=stations.value.filter(s=>s.assetLibraryConfig).map(s=>({stationId:s.id,stationName:s.name,...s.assetLibraryConfig}))};const edit=(id:string)=>{source.value=stations.value.find(s=>s.id===id)||null;draft.value=source.value?.assetLibraryConfig?{...source.value.assetLibraryConfig,fields:{...source.value.assetLibraryConfig.fields}}:null;dialog.value=Boolean(draft.value)};const copy=(id:string)=>{edit(id);if(draft.value)draft.value.name=`${draft.value.name} 副本`};const create=()=>ElMessage.info('请先在中转站选择素材库预设，再复制为新素材库');const save=async()=>{if(!source.value||!draft.value)return;await adminApi.updateRelayStation(source.value.id,{name:source.value.name,baseUrl:source.value.baseUrl,appendApiV3:source.value.appendApiV3,modelRedirects:source.value.modelRedirects,assetLibraryConfig:draft.value,isActive:source.value.isActive,isPrimary:source.value.isPrimary});dialog.value=false;await load();ElMessage.success('素材库配置已保存')};onMounted(load)</script><style scoped>.admin-page{width:min(1120px,100%);margin:0 auto}.page-header{display:flex;justify-content:space-between;align-items:center;padding-bottom:16px;border-bottom:1px solid var(--border-subtle)}.library-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:14px;margin-top:18px}.library-card{padding:18px;border:1px solid var(--border-default);border-radius:8px;background:var(--bg-secondary)}.library-card h2{margin:0;color:var(--text-primary)}.library-card p{color:var(--text-muted)}.field-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 12px}</style>
